  Theorem read_run :
    exists fxE RE ME,
      msteps RSEGS (st fx R 0x64568 M) (st fxE RE 0x126588 ME)
      (* [comment removed for export] *)
      /\ getr RE (reg 17) = Z_to_bv 64 66 /\ getr RE (reg 10) = Z_to_bv 64 2 /\ getr RE (reg 11) = Z_to_bv 64 (S - 584) /\ getr RE (reg 12) = Z_to_bv 64 2
      /\ getr RE (reg 9) = Z_to_bv 64 1319120 /\ getr RE (reg 18) = Z_to_bv 64 2 /\ getr RE (reg 19) = Z_to_bv 64 (S - 584) /\ getr RE (reg 22) = Z_to_bv 64 (n + 20)
      /\ L5.u64_at RSEGS ME (S - 584) (S - 464) /\ L5.u64_at RSEGS ME (S - 576) (n + 20) /\ L5.u64_at RSEGS ME (S - 568) 0 /\ L5.u64_at RSEGS ME (S - 560) 0
      /\ rdn RSEGS ME (Z_to_bv 64 (S - 464)) (19 + (length bs + 1)) = Some (PRE19 ++ bs ++ SUF1)
      /\ L5.u32_at RSEGS ME 1319240 2
      /\ agree0 M ME S /\ mem_grows M ME
      (* [comment removed for export] *)
      /\ (forall fx' RX MX,
            (forall x : word, ~ (S - 584 <= bv_unsigned x < S - 552) -> MX x = ME x) -> mem_grows ME MX ->
            (forall k, In k [2; 3; 4; 8; 9; 21; 23; 24; 25; 26; 27]%nat -> getr RX (reg k) = getr RE (reg k)) ->
            exists fxF RF MF,
              msteps RSEGS (st fx' RX 0x126594 MX) (st fxF RF 0x11eba4 MF)
              /\ getr RF (reg 10) = Z_to_bv 64 2 /\ getr RF (reg 2) = Z_to_bv 64 S
              /\ agree0 M MF S /\ mem_grows M MF
              /\ L5.u32_at RSEGS MF 1319120 5 /\ L5.u64_at RSEGS MF 1319216 0 /\ L5.u64_at RSEGS MF 1319208 6924696
